import {seeded} from '../3d/math.js';
/** Quiet, original procedural wind/stream bed. No recording, network or owned global context. */
export function createForestAmbience({contextFactory,getSettings}){let ac,bus,sources=[],paused=false;function start(){if(ac||getSettings().muted)return;ac=contextFactory();if(ac.state==='suspended')ac.resume();bus=ac.createGain();bus.gain.value=0;bus.connect(ac.destination);const buffer=ac.createBuffer(1,ac.sampleRate*4,ac.sampleRate),data=buffer.getChannelData(0),random=seeded(44112);for(let i=0;i<data.length;i++)data[i]=random()*2-1;for(const[type,frequency,level]of [['lowpass',420,.45],['bandpass',1700,.14]]){const source=ac.createBufferSource(),filter=ac.createBiquadFilter(),gain=ac.createGain();source.buffer=buffer;source.loop=true;filter.type=type;filter.frequency.value=frequency;filter.Q.value=.4;gain.gain.value=level;source.connect(filter);filter.connect(gain);gain.connect(bus);source.start();sources.push({source,filter,gain});}update();}
 function update(){if(!bus||!ac)return;const s=getSettings();bus.gain.setTargetAtTime(paused||s.muted?0:(s.volume??.5)*.035,ac.currentTime,.15);}
 return{start,update,pause(value){paused=value;update();},dispose(){for(const{source,filter,gain}of sources){try{source.stop();}catch{}source.disconnect();filter.disconnect();gain.disconnect();}sources=[];bus?.disconnect();bus=null;ac=null;}};
}
